from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,zipfile,shutil
root=Path.cwd();task=root/'CAD/Design_Completion';assembly=task/'RevB_Isolated/RB_Assem20_Design_RevB.SLDASM'
required=['BLADE_CARTRIDGE_INTEGRATION_STATE.json','SOCKET_CAP_INTEGRATION_STATE.json','ARM_RETENTION_INTEGRATION_STATE.json','ARM_SCREW_LENGTH_CORRECTION.json','MATERIAL_CORRECTION_STATE.json','SECONDARY_MATERIAL_ASSIGNMENTS.json','RESTORED_MOTION_CONSTRAINTS.json']
for name in required:assert json.loads((task/name).read_text()).get('complete'),name
for name in ['BLADE_SUPPORT_STATIC_CHECK.json','SOCKET_CAP_STATIC_CHECK.json','ARM_PIN_STATIC_CHECK.json','ARM_SCREW_STATIC_CHECK.json']:assert json.loads((task/name).read_text())['result']=='passed',name
motion=json.loads((task/'RESTORED_MOTION_CONSTRAINTS.json').read_text());window=json.loads((task/'FINAL_WINDOW_CLEANUP.json').read_text());assert not motion['mate_errors'] and not window['assembly_save_flag']
sha=hashlib.sha256(assembly.read_bytes()).hexdigest();assert sha==motion['assembly_sha256']==window['assembly_sha256']
index=json.loads((task/'Drawings_Prototype/DRAWING_INDEX.json').read_text());assert len(index['drawings'])==32
for row in index['drawings'].values():
 assert hashlib.sha256(Path(row['model']).read_bytes()).hexdigest()==row['model_sha256']
 for field in ['drawing','pdf']:assert hashlib.sha256(Path(row[field]).read_bytes()).hexdigest()==row[field+'_sha256']
baseline=hashlib.sha256((root/'config/baseline.json').read_bytes()).hexdigest();assert baseline=='2445c7153775b1930e21b65a5d95e5b26c7632c273e1867abcc6c3a6d830fa7f'
stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ');checkpoint=task/'Checkpoints'/stamp;checkpoint.mkdir()
files=[p for p in (task/'RevB_Isolated').rglob('*') if p.is_file() and p.suffix.upper() in ('.SLDPRT','.SLDASM') and not p.name.startswith('~$')]
files += [Path(row[key]) for row in index['drawings'].values() for key in ['drawing','pdf']]
files += [task/'Materials/CycloProp_Prototype_Densities.sldmat',task/'Materials/DATABASE_INSTALLATION.json',task/'Materials/README.md']
manifest={str(p.relative_to(task)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in files}
archive=checkpoint/'SAVED_NATIVE_AND_DRAWINGS.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED,compresslevel=3) as z:
 for p in files:z.write(p,str(p.relative_to(task)))
for name in required+['MECHANICAL_COMPLETION_REPORT.md','FIT_TOLERANCE_AND_PHYSICAL_RELEASE_REGISTER.md','REVISED_NATIVE_MATERIAL_BOM.json','REVISED_NATIVE_MATERIAL_BOM.csv','SERVO_LOAD_AND_INTERFACE_SCREEN.json','ARM_ROD_RETENTION_STRENGTH_SCREEN.json','ARM_SCREW_STATIC_CHECK.json','ORIGINAL_AND_BASELINE_PRESERVATION_CHECK.json','FINAL_WINDOW_CLEANUP.json','ASSEMBLY_BOM_DRAWING_STATE.json']:
 shutil.copy2(task/name,checkpoint/name)
state={'status':'CURRENT PASS SAVED; overall design/manufacturing task remains incomplete','saved_utc':datetime.now(timezone.utc).isoformat(),'working_assembly':str(assembly),'assembly_sha256':sha,'baseline_sha256':baseline,'checkpoint_folder':str(checkpoint),'archive':str(archive),'archive_sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'native_model_files':len([p for p in files if p.suffix.upper() in ('.SLDPRT','.SLDASM')]),'active_native_drawing_PDF_pairs':32,'manifest':manifest,'mate_errors':[],'motion_constraints':'Both construction angle holds suppressed; X/Y and existing radial advanced limits active; saved shaft/blade/carriage transforms preserved. No new full free-motion campaign.','remaining':['Adequately rated actuator/ratio and exact supplier servo/horn fit','Approved loads/life and actual blade mass/inertia','Composite blade/metal trunnion construction and bond; bearing/pin fits and validation','Joint/adhesive/locking qualification, remaining short guide threads and custom hardware release','Full legacy manufacturing definitions/drawings, assembly balloons and tolerance release','Final moving-clearance/backlash verification on final frozen geometry; guarded physical tests'],'resume_rule':'Read current report and saved integration states. Do not rerun completed mutators or revert to the historical paused323-root assembly.'}
(task/'CURRENT_IMPLEMENTATION_CHECKPOINT.json').write_text(json.dumps(state,indent=2));(checkpoint/'MANIFEST.json').write_text(json.dumps(state,indent=2))
(task/'RESUMED_PROGRESS.json').write_text(json.dumps({k:v for k,v in state.items() if k!='manifest'},indent=2))
notes=f'''# Current resume notes\n\nSaved {state['saved_utc']}. This supersedes the historical PAUSED_RESUME_NOTES.md/PAUSE_CHECKPOINT.json as the current entry point. The user resumed the task and then prioritized a fast saved pass. This is a saved checkpoint, not an overall completion or operating release.\n\nRead MECHANICAL_COMPLETION_REPORT.md and CURRENT_IMPLEMENTATION_CHECKPOINT.json first. Working assembly: RevB_Isolated/RB_Assem20_Design_RevB.SLDASM. The saved native tree has98 model files and31 active drawing/PDF pairs. Recovery archive: {archive.relative_to(task)}. Restore files to their original task-relative locations; the archive is a recovery snapshot, not a separately validated cross-machine Pack and Go. Install the retained material database in a configured material folder on another machine and verify references/densities.\n\nNew interfaces are installed and saved: eight bearing cartridges; symmetric0.65mm hub shims and longer bolts; eight capped sockets; four arm crosspins; four longer arm-sideM2x12 screws. Follow ARM_SCREW_LENGTH_CORRECTION.json for the new screw names; REV_B_STATE.json contains historical old screw names. Native saved-pose checks passed202/98/8/36 comparisons respectively. Current travel constraints are restored and both angle holds suppressed; the active-mate scan found no errors.\n\nMaterials/density corrections and their backups are complete for the listed primary/secondary parts. Remaining14g servo override is explicitly manufacturer-nominal reference mass. The mixed native mass sum is1109.958g, not hardware mass. Servo selection fails the provisional X-axis torque screen.\n\nDrawings are PROTOTYPE / NOT RELEASED FOR FABRICATION, with dimensional/interface notes, source hashes, DO NOT SCALE labels and release holds.32 active PDFs passed text/source checks and were rendered; contact-sheet layouts and representative full-size pages inspected. Two inactive candidates archived under Drawings_Prototype/Superseded_Candidates. Native parts-only assembly BOM CP-RB-002 is complete for reference quantities; legacy manufacturing completeness, GD&T and assembly balloons remain open.\n\nNext work: close named actuator/load/composite/supplier dependencies; finish remaining manufacturability and final moving-clearance/backlash checks. Do not claim fatigue, physical retention, actual supplied fit, measured mass or2640RPM capability. No baseline inputs/original sources were changed.\n\nDo not rerun completed integration/material scripts. Debug draft inspect_material_database.py is disabled. Native operations must remain serial. Keep unused windows closed and preserve dirty task data before closing.\n'''
(task/'CURRENT_RESUME_NOTES.md').write_text(notes)
print('CHECKPOINT_SAVED',str(checkpoint),'native_models',state['native_model_files'],'drawings',32,'archive_MB',round(archive.stat().st_size/1e6,2))
